package plates.core.input

import plates.core.alphabet.AlphabetInput

/** [input] shows editable fields; [display] shows bare glyphs, as printed. */
public enum class PlateMode { INPUT, DISPLAY }

/** What a slot does about input, resolved once per build. */
public enum class SlotBehavior { GLYPH, IME_FIELD, HARDWARE_FIELD, EXTERNAL_FIELD, KEYPAD_FIRST_FIELD, SHEET }

/** A chosen alphabet reaches [SlotBehavior.SHEET] only under [PlateInputSource.SYSTEM]. */
public fun resolveSlotBehavior(mode: PlateMode, input: AlphabetInput, source: PlateInputSource): SlotBehavior =
    if (mode == PlateMode.DISPLAY) SlotBehavior.GLYPH
    else when (source) {
        PlateInputSource.SYSTEM -> if (input == AlphabetInput.TYPED) SlotBehavior.IME_FIELD else SlotBehavior.SHEET
        PlateInputSource.HARDWARE_KEYBOARD -> SlotBehavior.HARDWARE_FIELD
        PlateInputSource.PACKAGE_KEYPAD, PlateInputSource.HOST -> SlotBehavior.EXTERNAL_FIELD
        PlateInputSource.KEYPAD_FIRST -> SlotBehavior.KEYPAD_FIRST_FIELD
    }
